1body {
2  font-family: sans-serif;
3  padding: 20px;
4}
5
6.error {
7  display: block;
8  color: #dc2626;
9  font-size: 12px;
10  margin-bottom: 8px;
11}
12
13.success {
14  margin-top: 12px;
